head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCaption]<br/>GridView 의 Body Table 에 caption 요소를 설정합니다.",
    "validation" : [
        "GridView 의 Body Table 에 caption 요소를 설정합니다.",
        "label(필수) 파라미터로 Body Table 의 caption 요소에 적용될 텍스트를 설정합니다.",
        "caption 요소가 이미 존재하면 텍스트를 교체하고, 존재하지 않으면 새로 생성하여 Body Table 의 colgroup 앞에 삽입합니다. captionAuto 속성값에 관계없이 기존 텍스트를 제거하고 파라미터값으로 재설정합니다.",
        "caption 요소에 'setcaption' CSS 클래스를 추가합니다. 메소드를 반복 호출하면 CSS 클래스가 중복 추가될 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // 조건 읽기
    //  - con_captionAuto : true 이면 렌더 시 caption 요소가 자동 생성됨(setcaption 클래스 포함, 초기 caption 존재)
    //                      false 이면 caption 요소 없음 → setCaption 호출 시 새로 생성
    let captionAutoVal = con_captionAuto.getValue();
    let isCaptionAuto = (captionAutoVal === 'true');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // Property 설정은 createCList 공통 함수 사용
    let cList = $c.gcm.createCList({ captionAuto: captionAutoVal, dataList: "data:dlt_bind", checkAllType: "false" });

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblCaption = isCaptionAuto ? 'captionAuto=true (렌더 시 Body caption 요소 자동 생성)' : 'captionAuto=false (Body caption 요소 없음)';
    $c.gcm.createLabel('label="' + lblCaption + ' 로 GridView 생성 (Header 4컬럼 + gBody)"', '', 'label1');

    // target 생성 (captionAuto 조건부)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:300px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="사번"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="이름"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="부서"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="직급"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Body Table 의 caption 요소 반환 (없으면 null)
scwin.getBodyCaption = function () {
    let bodyTable = document.querySelector("table[id*='target1_body_table']");
    if (!bodyTable) {
        return null;
    }
    return bodyTable.getElementsByTagName("caption")[0] || null;
}



// Body Table 의 caption 요소가 colgroup 앞에 위치하는지 확인 (@spec1)
//  - caption 요소가 colgroup 의 바로 이전 형제(previousElementSibling)인지로 판단
scwin.isCaptionBeforeColgroup = function () {
    let bodyTable = document.querySelector("table[id*='target1_body_table']");
    if (!bodyTable) {
        return null;
    }
    let caption = bodyTable.getElementsByTagName("caption")[0];
    let colgroup = bodyTable.getElementsByTagName("colgroup")[0];
    if (!caption || !colgroup) {
        return false;
    }
    return colgroup.previousElementSibling === caption;
}



// 'setcaption' CSS 클래스 개수 (반복 호출 시 중복 추가 확인 @spec2)
scwin.getSetcaptionCount = function () {
    let caption = scwin.getBodyCaption();
    if (!caption) {
        return 0;
    }
    let cls = (caption.className || '').split(/\s+/).filter(function (c) { return c === 'setcaption'; });
    return cls.length;
}



// 현재 Body Table caption 요소 상태 확인 (setCaption 호출 전 사전 상태)
scwin.btn_checkCaption_onclick = function () {
    let caption = scwin.getBodyCaption();
    wf_body_bottom.getObj("scwin").setReturnValue("[현재 Body caption 요소] " + (caption === null ? '미생성(caption 요소 없음)' : "'" + caption.textContent + "'"));
    wf_body_bottom.getObj("scwin").setReturnValue("['setcaption' 클래스 개수] " + scwin.getSetcaptionCount());
}



// setCaption 호출 후 caption 텍스트 / colgroup 앞 위치 / setcaption 클래스 개수 출력
scwin.btn_setCaption_onclick = function () {
    let label = par_label.getValue();
    target1.setCaption(label);

    let caption = scwin.getBodyCaption();
    wf_body_bottom.getObj("scwin").setReturnValue("setCaption('" + label + "') 호출");
    // @spec1 : caption 텍스트 설정/교체, colgroup 앞 삽입 (captionAuto 무관)
    wf_body_bottom.getObj("scwin").setReturnValue("[Body caption 텍스트] " + (caption ? "'" + caption.textContent + "'" : 'null'));
    wf_body_bottom.getObj("scwin").setReturnValue("[caption 이 colgroup 앞에 위치] " + scwin.isCaptionBeforeColgroup());
    // @spec2 : 'setcaption' 클래스 추가 (반복 호출 시 중복 → 개수 증가)
    wf_body_bottom.getObj("scwin").setReturnValue("['setcaption' 클래스 개수] " + scwin.getSetcaptionCount());
}
